import sys

def main():
    n = int(sys.stdin.read().split()[0])
    stack = [n]
    op = 0  # 0: *, 1: /, 2: +, 3: -
    for x in range(n - 1, 0, -1):
        if op == 0:
            stack.append(stack.pop() * x)
        elif op == 1:
            top = stack.pop()
            stack.append(top // x if top >= 0 else -((-top) // x))
        elif op == 2:
            stack.append(x)
        else:
            stack.append(-x)
        op = (op + 1) % 4
    print(sum(stack))

